"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { 
  Trophy, Users, Star, Crown, 
  ArrowUpRight, Loader2, Search, Zap,
  TrendingUp, Award, UserCheck, Mail, Phone, Calendar,
  ListFilter, Store
} from "lucide-react";

export default function WaitlistIntelligencePage() {
  const [waitlistRank, setWaitlistRank] = useState<any[]>([]);
  const [vendorRank, setVendorRank] = useState<any[]>([]);
  const [fullRegistry, setFullRegistry] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchIntelligence();
  }, []);

  async function fetchIntelligence() {
    setLoading(true);
    
    // 1. Fetch Top Waitlist Recruiters
    const { data: waitlistData } = await supabase
      .from('waitlist')
      .select('business_name, email, referral_count, created_at')
      .order('referral_count', { ascending: false })
      .limit(10);

    // 2. Fetch Top Vendor Recruiters
    const { data: vendorData } = await supabase
      .from('stores')
      .select('name, referral_count, subscription_plan')
      .order('referral_count', { ascending: false })
      .limit(10);

    // 3. 🔥 MASTER AUDIT: Pulling from BOTH Waitlist and Stores to see everyone
    const { data: waitlistEntries } = await supabase
      .from('waitlist')
      .select('business_name, email, phone, referral_count, created_at')
      .order('created_at', { ascending: false });

    const { data: storeEntries } = await supabase
      .from('stores')
      .select('name, owner_email, whatsapp_number, referral_count, created_at')
      .order('created_at', { ascending: false });

    // Combine and format for the table
    const combined = [
      ...(waitlistEntries || []).map(w => ({ ...w, type: 'Waitlist' })),
      ...(storeEntries || []).map(s => ({
        business_name: s.name,
        email: s.owner_email,
        phone: s.whatsapp_number,
        referral_count: s.referral_count,
        created_at: s.created_at,
        type: 'Live Store'
      }))
    ].sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

    setWaitlistRank(waitlistData || []);
    setVendorRank(vendorData || []);
    setFullRegistry(combined);
    setLoading(false);
  }

  const filteredRegistry = fullRegistry.filter(entry => 
    entry.business_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    entry.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    entry.phone?.includes(searchTerm)
  );

  if (loading) return (
    <div className="h-96 flex flex-col items-center justify-center gap-4">
      <Loader2 className="animate-spin text-emerald-500" size={40} />
      <p className="text-gray-500 font-black uppercase tracking-widest text-[10px]">Processing Empire Intelligence...</p>
    </div>
  );

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      
      {/* --- HEADER --- */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h2 className="text-3xl font-black text-white uppercase tracking-tighter italic">Growth Intelligence</h2>
          <p className="text-gray-400 text-sm font-medium">Tracking the recruiters building the StoreLink Empire.</p>
        </div>
        <button onClick={fetchIntelligence} className="px-6 py-2 bg-gray-900 border border-gray-800 rounded-xl text-[10px] font-black uppercase text-gray-400 hover:text-white transition-all flex items-center gap-2">
          <RefreshCcw size={14} /> Refresh Ranks
        </button>
      </div>

      {/* --- LEADERBOARDS --- */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Waitlist Champions Section */}
        <div className="space-y-6">
          <div className="flex items-center gap-3 px-2">
            <div className="p-2 bg-blue-500/10 text-blue-500 rounded-xl border border-blue-500/20"><Users size={20} /></div>
            <h3 className="font-black text-xl text-white uppercase tracking-tighter italic">Waitlist Champions</h3>
          </div>
          <div className="bg-gray-900/40 border border-gray-800 rounded-[2.5rem] p-6 backdrop-blur-sm shadow-2xl">
            <div className="space-y-4">
              {waitlistRank.map((user, idx) => (
                <div key={user.email} className="flex items-center justify-between p-4 bg-black/20 rounded-2xl border border-white/5 group hover:border-blue-500/30 transition-all">
                  <div className="flex items-center gap-4">
                    <span className={`text-sm font-black italic ${idx < 3 ? 'text-amber-500' : 'text-gray-600'}`}>#{idx + 1}</span>
                    <div>
                      <p className="text-sm font-bold text-white uppercase tracking-tight">{user.business_name || "New Merchant"}</p>
                      <p className="text-[10px] text-gray-500">{user.email}</p>
                    </div>
                  </div>
                  <p className="text-xl font-black text-blue-500 italic">{user.referral_count}</p>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Active Ambassadors Section */}
        <div className="space-y-6">
          <div className="flex items-center gap-3 px-2">
            <div className="p-2 bg-emerald-500/10 text-emerald-500 rounded-xl border border-emerald-500/20"><Crown size={20} /></div>
            <h3 className="font-black text-xl text-white uppercase tracking-tighter italic">Active Ambassadors</h3>
          </div>
          <div className="bg-gray-900/40 border border-gray-800 rounded-[2.5rem] p-6 backdrop-blur-sm shadow-2xl">
            <div className="space-y-4">
              {vendorRank.map((store, idx) => (
                <div key={store.name} className="flex items-center justify-between p-4 bg-black/20 rounded-2xl border border-white/5 group hover:border-emerald-500/30 transition-all">
                  <div className="flex items-center gap-4">
                    <span className={`text-sm font-black italic ${idx < 3 ? 'text-amber-500' : 'text-gray-600'}`}>#{idx + 1}</span>
                    <div>
                      <p className="text-sm font-bold text-white uppercase tracking-tight">{store.name}</p>
                      <span className="text-[9px] px-2 py-0.5 bg-gray-800 text-gray-400 rounded-md font-black uppercase">Plan: {store.subscription_plan}</span>
                    </div>
                  </div>
                  <p className="text-xl font-black text-emerald-500 italic">{store.referral_count}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* --- 🔥 MASTER REGISTRY (SCROLLABLE) --- */}
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 px-2">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-amber-500/10 text-amber-500 rounded-xl border border-amber-500/20"><ListFilter size={20} /></div>
            <div>
              <h3 className="font-black text-xl text-white uppercase tracking-tighter italic">Master Registry</h3>
              <p className="text-[9px] text-gray-500 font-black uppercase tracking-widest">Growth Loop Database ({filteredRegistry.length} Entries)</p>
            </div>
          </div>
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
            <input type="text" placeholder="Search name, email or phone..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-gray-900 border border-gray-800 rounded-2xl py-3 pl-12 pr-4 text-sm text-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all shadow-xl" />
          </div>
        </div>

        {/* 🛡️ FIXED HEIGHT SCROLL CONTAINER */}
        <div className="bg-gray-900/40 border border-gray-800 rounded-[2.5rem] overflow-hidden backdrop-blur-sm shadow-2xl">
          <div className="max-h-[500px] overflow-y-auto custom-scrollbar">
            <table className="w-full text-left border-collapse">
              <thead className="bg-black/60 sticky top-0 z-10 border-b border-gray-800">
                <tr>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic">Identity</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic">Source</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic text-center">Referrals</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic text-right">Joined</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800/50">
                {filteredRegistry.map((entry) => (
                  <tr key={entry.email} className="group hover:bg-emerald-500/5 transition-colors">
                    <td className="px-6 py-5">
                      <p className="text-sm font-black text-white uppercase tracking-tight italic">{entry.business_name || "New Merchant"}</p>
                      <div className="flex items-center gap-4 mt-1">
                        <span className="text-[10px] text-gray-500 flex items-center gap-1"><Mail size={10} /> {entry.email}</span>
                        <span className="text-[10px] text-gray-500 flex items-center gap-1"><Phone size={10} /> {entry.phone}</span>
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <span className={`px-2 py-1 rounded text-[8px] font-black uppercase ${entry.type === 'Live Store' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-blue-500/10 text-blue-500'}`}>
                        {entry.type}
                      </span>
                    </td>
                    <td className="px-6 py-5 text-center">
                      <div className="text-sm font-black text-white">{entry.referral_count}</div>
                    </td>
                    <td className="px-6 py-5 text-right">
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">
                        {new Date(entry.created_at).toLocaleDateString('en-NG', { day: 'numeric', month: 'short' })}
                      </p>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* --- FOOTER BANNER --- */}
      <div className="bg-amber-500/5 border border-amber-500/10 p-8 rounded-[2.5rem] flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-amber-500/20 text-amber-500 rounded-2xl flex items-center justify-center"><Star size={24} fill="currentColor" /></div>
          <div><h4 className="text-white font-black uppercase italic tracking-tight">Priority Alpha Selection</h4><p className="text-gray-400 text-xs">Selection is based on the Top Recruiters from both active vendors and waitlist users.</p></div>
        </div>
        <button className="px-8 py-4 bg-amber-500 text-black font-black uppercase text-[10px] tracking-widest rounded-2xl hover:scale-105 transition-transform shadow-xl shadow-amber-500/20">Prepare Launch Invites</button>
      </div>
    </div>
  );
}